import { extend } from 'flarum/common/extend';
import Component from 'flarum/common/Component';
let list = null;

/**
 * Loads ConsentList (its own chunk, with the sponsors API) the first time the
 * settings page is opened: every other page stays as light as before.
 */
class LazyConsentList extends Component {
  oncreate(vnode) {
    super.oncreate(vnode);
    if (!list) {
      import(/* webpackChunkName: 'forum/sponsors/ConsentList', webpackMode: 'lazy-once' */ './ConsentList').then(mod => {
        list = mod.default;
        m.redraw();
      });
    }
  }
  view() {
    return list ? m(list) : m("span", null);
  }
}

/** "Sponsors you share your email with", in the member's settings. */
export default function addToSettings() {
  extend('flarum/forum/components/SettingsPage', 'settingsItems', function (items) {
    items.add('giveawaySponsors', m(LazyConsentList, null), -20);
  });
}
