import app from 'flarum/forum/app';
import { extend } from 'flarum/common/extend';
import IndexSidebar from 'flarum/forum/components/IndexSidebar';
import LinkButton from 'flarum/common/components/LinkButton';
import CommentPost from 'flarum/forum/components/CommentPost';
import scanForGiveaways from './embed/scan';
import addToComposer from './composer/addToComposer';
import { registerTodayWidget } from './advent/todayWidget';
import addToSettings from './sponsors/addToSettings';
export { default as extend } from './extend';
app.initializers.add('ernestdefoe-giveaways', () => {
  // Nav link sits with "All Discussions" in the sidebar navigation. Flarum 2
  // exposes these via IndexSidebar.navItems (IndexPage no longer owns the nav).
  extend(IndexSidebar.prototype, 'navItems', function (items) {
    if (app.forum.attribute('giveawaysShowNav') === false) return;
    const label = app.forum.attribute('giveawaysNavLabel') || app.translator.trans('ernestdefoe-giveaways.forum.nav');
    items.add('giveaways', LinkButton.component({
      href: app.route('giveaways.index'),
      icon: 'fas fa-gift'
    }, label), 5);
  });

  // A giveaway link on its own line in a post shows as the giveaway's card.
  // onupdate too: an edited post replaces its content, links and all.
  extend(CommentPost.prototype, ['oncreate', 'onupdate'], function () {
    scanForGiveaways(this.element);
  });
  addToComposer();
  addToSettings();

  // After the hosts' own initializers have run.
  setTimeout(() => registerTodayWidget(), 0);
});